<?php
namespace Pterodactyl\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Pterodactyl\Services\Nodexa\CheckoutService;use Pterodactyl\Services\Nodexa\PaymentCompletionService;
class CheckoutController extends Controller {
 public function start(Request $r,int $invoice,CheckoutService $checkout){$user=$r->user();$i=DB::table('invoices')->where('id',$invoice)->where('user_id',$user->id)->first();abort_unless($i,404);$o=$i->order_id?DB::table('billing_orders')->where('id',$i->order_id)->where('user_id',$user->id)->first():null;abort_unless($o,404);$g=DB::table('payment_gateways')->where('gateway',$o->payment_method)->where('enabled',true)->first();if(!$g)return back()->withErrors(['payment'=>'Den valgte betalingsmetode er ikke aktiv.']);try{$session=$checkout->create($i,$o,$g);if(($session['status']??'')==='paid')return redirect($session['redirect']);if(($session['status']??'')==='test')return back()->with('checkout_test',$session);if(!empty($session['redirect']))return redirect()->away($session['redirect']);return back()->withErrors(['payment'=>$session['message']??'Betalingssessionen kunne ikke startes.']);}catch(\Throwable $e){report($e);return back()->withErrors(['payment'=>$e->getMessage()]);}}
 public function testComplete(Request $r,int $invoice,PaymentCompletionService $payments){$user=$r->user();$i=DB::table('invoices')->where('id',$invoice)->where('user_id',$user->id)->first();abort_unless($i,404);$o=$i->order_id?DB::table('billing_orders')->where('id',$i->order_id)->where('user_id',$user->id)->first():null;abort_unless($o,404);$g=DB::table('payment_gateways')->where('gateway',$o->payment_method)->where('enabled',true)->where('test_mode',true)->first();abort_unless($g,403);try{$payments->complete($i->id,$g->gateway,'TEST-'.$i->id.'-'.now()->timestamp,(float)$i->total,['source'=>'nodexa_test_checkout']);return redirect('/client/invoices/'.$i->id)->with('success','Testbetalingen blev gennemført, og automatisk provisioning blev forsøgt.');}catch(\Throwable $e){report($e);return back()->withErrors(['payment'=>$e->getMessage()]);}}
}
